CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE catalog_clock(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), value bigint NOT NULL DEFAULT 0, minimum_cursor bigint NOT NULL DEFAULT 0);
INSERT INTO catalog_clock(singleton) VALUES(true);
CREATE TABLE source_origins(id uuid PRIMARY KEY, origin text UNIQUE NOT NULL, policy jsonb NOT NULL, health text NOT NULL DEFAULT 'not_fetched', last_attempt_at timestamptz, last_success_at timestamptz, last_content_change_at timestamptz, next_allowed_at timestamptz NOT NULL DEFAULT now(), daily_requests integer NOT NULL DEFAULT 0, daily_bytes bigint NOT NULL DEFAULT 0, fetch_lease_until timestamptz, fetch_lease_token uuid, budget_date date NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE source_documents(id uuid PRIMARY KEY, origin_id uuid NOT NULL REFERENCES source_origins, fetch_url text NOT NULL, identity_url text UNIQUE NOT NULL, adapter_id text, enabled boolean NOT NULL DEFAULT false, next_fetch_at timestamptz NOT NULL DEFAULT now(), etag text, last_modified text, last_snapshot_id uuid, health text NOT NULL DEFAULT 'not_fetched');
CREATE TABLE source_snapshots(id uuid PRIMARY KEY, document_id uuid NOT NULL REFERENCES source_documents, content_hash text NOT NULL, body text NOT NULL, metadata jsonb NOT NULL, observed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(document_id,content_hash));
ALTER TABLE source_documents ADD CONSTRAINT last_snapshot_fk FOREIGN KEY(last_snapshot_id) REFERENCES source_snapshots;
CREATE TABLE source_fetches(id uuid PRIMARY KEY, document_id uuid NOT NULL REFERENCES source_documents, outcome text NOT NULL, metadata jsonb NOT NULL, observed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE entity_aliases(source_key text PRIMARY KEY, entity_id uuid NOT NULL, kind text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE events(id text PRIMARY KEY, revision integer NOT NULL, bundle jsonb NOT NULL, content_hash text NOT NULL, deleted boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE editions(id text PRIMARY KEY,event_id text NOT NULL REFERENCES events, data jsonb NOT NULL);
CREATE TABLE stops(id text PRIMARY KEY,event_id text NOT NULL REFERENCES events,edition_id text REFERENCES editions, data jsonb NOT NULL);
CREATE TABLE performances(id text PRIMARY KEY,event_id text NOT NULL REFERENCES events,stop_id text REFERENCES stops,edition_id text REFERENCES editions,local_date date,data jsonb NOT NULL);
CREATE TABLE event_revisions(event_id text NOT NULL REFERENCES events, revision integer NOT NULL, bundle jsonb NOT NULL, content_hash text NOT NULL, reason text NOT NULL, reviewer text NOT NULL, published_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(event_id,revision));
CREATE TABLE review_cases(id uuid PRIMARY KEY,event_id text NOT NULL,base_revision integer NOT NULL, proposal jsonb NOT NULL, issues jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','accepted','rejected')), reason text, reviewer text,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE fact_candidates(id uuid PRIMARY KEY,snapshot_id uuid NOT NULL REFERENCES source_snapshots, source_key text NOT NULL,kind text NOT NULL,data jsonb NOT NULL,evidence jsonb NOT NULL,issues jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX fact_candidate_identity ON fact_candidates(snapshot_id,source_key,kind,(evidence->'evidence'->>'locator'));
CREATE TABLE accepted_facts(event_id text NOT NULL REFERENCES events,revision integer NOT NULL,record_id text NOT NULL,field text NOT NULL,evidence jsonb NOT NULL,PRIMARY KEY(event_id,revision,record_id,field));
CREATE TABLE scoped_records(id text PRIMARY KEY,event_id text NOT NULL REFERENCES events,kind text NOT NULL,data jsonb NOT NULL);
CREATE TABLE applicability_members(record_id text NOT NULL REFERENCES scoped_records ON DELETE CASCADE,performance_id text NOT NULL REFERENCES performances,PRIMARY KEY(record_id,performance_id));
CREATE TABLE ticket_offers(id text PRIMARY KEY,event_id text NOT NULL REFERENCES events,round_id text NOT NULL REFERENCES scoped_records,tier_id text NOT NULL REFERENCES scoped_records,data jsonb NOT NULL);
CREATE TABLE catalog_changes(sequence bigint PRIMARY KEY,event_id text NOT NULL,revision integer NOT NULL,kind text NOT NULL CHECK(kind IN('upsert','delete','remap')),bundle jsonb,replacement_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events(id uuid PRIMARY KEY,dedupe_key text UNIQUE NOT NULL,event_id text NOT NULL,revision integer NOT NULL,kind text NOT NULL,payload jsonb NOT NULL,processed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id uuid PRIMARY KEY,kind text NOT NULL,payload jsonb NOT NULL,dedupe_key text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','done','failed')),attempts integer NOT NULL DEFAULT 0,max_attempts integer NOT NULL DEFAULT 3,run_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,fencing_token uuid,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_ready ON jobs(run_at) WHERE status IN('queued','running');
CREATE TABLE installations(id uuid PRIMARY KEY,credential_hash text NOT NULL,push_token text,environment text NOT NULL DEFAULT 'sandbox' CHECK(environment IN('sandbox','production')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscriptions(installation_id uuid NOT NULL REFERENCES installations ON DELETE CASCADE,event_id text NOT NULL,performance_ids jsonb NOT NULL DEFAULT '[]',changes_enabled boolean NOT NULL DEFAULT true,PRIMARY KEY(installation_id,event_id));
CREATE TABLE reminders(id uuid PRIMARY KEY,installation_id uuid NOT NULL REFERENCES installations ON DELETE CASCADE,event_id text NOT NULL,performance_id text NOT NULL,record_id text NOT NULL,field text NOT NULL,lead_seconds integer NOT NULL CHECK(lead_seconds>=0),enabled boolean NOT NULL DEFAULT true,UNIQUE(installation_id,event_id,performance_id,record_id,field));
CREATE TABLE notification_deliveries(id uuid PRIMARY KEY,installation_id uuid NOT NULL REFERENCES installations ON DELETE CASCADE,dedupe_key text UNIQUE NOT NULL,event_id text NOT NULL,revision integer NOT NULL,payload jsonb NOT NULL,send_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,last_error text,lease_until timestamptz,lease_token uuid,delivered_at timestamptz);
CREATE TABLE reports(id uuid PRIMARY KEY,event_id text,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id uuid PRIMARY KEY,actor text NOT NULL,action text NOT NULL,target text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
